import 'package:result_monad/result_monad.dart';

Result<double, String> invert(double value) {
  if (value == 0) {
    return Error('Cannot invert zero');
  }
  return Ok(1.0 / value);
}

void main() {
  invert(2).match(
    onSuccess: (v) => print('Inverse is: $v'),
    onError: (e, _) => print(e),
  );
}
